TLM.f("Sancti/10-11",{"officium":"Maternitatis Beatæ Mariæ Virginis","rule":["ex C11;","Gloria","Credo","Prefatio=Maria=Festivitate;"],"ruleInherited":["Gloria","Credo","Prefatio=Maria=Festivitate","Gloria","Suffr=Spiritu;Ecclesiæ,Papa;;","Prefatio=Maria=veneratione;"],"fallback":"Commune/C11","from":{"GradualeP":"Commune/C11","Tractus":"Commune/C11"},"sections":{"Introitus":[{"k":"ref","la":"Isa 7:14"},{"k":"text","la":"Ecce Virgo concípiet, et páriet fílium, et vocábitur nomen ejus Emmánuel."},{"k":"ref","la":"Ps 97:1"},{"k":"text","la":"Cantáte Dómino cánticum novum: quia mirabília fecit."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Ecce Virgo concípiet, et páriet fílium, et vocábitur nomen ejus Emmánuel."}],"Oratio":[{"k":"text","la":"Deus, qui de beátæ Maríæ Vírginis útero Verbum tuum, Angelo nuntiánte, carnem suscípere voluísti: præsta supplícibus tuis; ut, qui vere eam Genitrícem Dei crédimus, ejus apud te intercessiónibus adjuvémur."},{"k":"macro","name":"Per eundem"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Eccli 24:23-31"},{"k":"text","la":"Ego quasi vitis fructificávi suavitátem odóris: et flores mei fructus honóris et honestátis. Ego mater pulchræ dilectiónis, et timóris, et agnitiónis, et sanctæ spei. In me grátia omnis viæ et veritátis: in me omnis spes vitæ et virtútis. Transíte ad me, omnes, qui concupíscitis me, et a generatiónibus meis implémini. Spíritus enim meus super mel dulcis, et heréditas mea super mel et favum. Memória mea in generatiónes sæculórum. Qui edunt me, adhuc esúrient: et qui bibunt me, adhuc sítient. Qui audit me, non confundétur: et qui operántur in me, non peccábunt. Qui elúcidant me, vitam ætérnam habébunt."}],"Graduale":[{"k":"ref","la":"Isa 11:1-2"},{"k":"text","la":"Egrediétur virga de rádice Jesse, et flos de rádice ejus ascéndet."},{"k":"text","la":"Et requiéscet super eum Spíritus Dómini.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"text","la":"Virgo Dei Génitrix, quem totus non capit orbis, in tua se clausit víscera factus homo. Allelúja.","mark":"V"}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Num 17:8"},{"k":"text","la":"Virga Jesse flóruit: Virgo Deum et hóminem génuit: pacem Deus réddidit, in se reconcílians ima summis"},{"k":"ref","la":"Luke 1:28"},{"k":"text","la":"Ave, María, grátia plena; Dóminus tecum: benedícta tu in muliéribus. Allelúja."}],"Tractus":[{"k":"text","la":"Benedícta et venerábilis es, Virgo María: quæ sine tactu pudóris invénia es Mater Salvatóris."},{"k":"text","la":"Virgo, Dei Génetrix, quem totus non capit orbis, in tua se clausit víscera factus homo.","mark":"V"},{"k":"text","la":"Gaude, María Virgo, cunctas hǽreses sola interemísti."},{"k":"text","la":"Quæ Gabriélis Archángeli dictis credidísti.","mark":"V"},{"k":"text","la":"Dum Virgo Deum et hóminem genuísti: et post partum, Virgo, invioláta permansísti.","mark":"V"},{"k":"text","la":"Dei Génetrix, intercéde pro nobis.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 2:43-51"},{"k":"text","la":"In illo témpore: Cum redírent, remánsit puer Jesus in Jerúsalem, et non cognovérunt paréntes ejus. Existimántes autem illum esse in comitátu, venérunt iter diei, et requirébant eum inter cognátos, et notos. Et non inveniéntes, regréssi sunt in Jerúsalem, requiréntes eum. Et factum est, post tríduum invenérunt illum in templo sedéntem in médio doctórum, audiéntem illos, et interrogántem eos. Stupébant autem omnes, qui eum audiébant, super prudéntia et respónsis ejus. Et vidéntes admiráti sunt. Et dixit mater ejus ad illum: Fili, quid fecísti nobis sic? ecce pater tuus, et ego doléntes quærebámus te. Et ait ad illos: Quid est quod me quærebátis? nesciebátis quia in his, quæ Patris mei sunt, opórtet me esse? Et ipsi non intellexérunt verbum, quod locútus est ad eos. Et descéndit cum eis, et venit Názareth: et erat súbditus illis."}],"Offertorium":[{"k":"ref","la":"Matt 1:18"},{"k":"text","la":"Cum esset desponsáta mater ejus María Joseph, invénta est in útero habens de Spíritu Sancto."}],"Secreta":[{"k":"text","la":"Tua, Dómine, propitiatióne, et beátae Maríae semper Vírginis, Unigéniti tui Matris, intercessióne, ad perpétuam atque praeséntem haec oblátio nobis profíciat prosperitátem et pacem."},{"k":"macro","name":"Per eumdem"}],"Communio":[{"k":"text","la":"Beáta víscera Maríæ Vírginis, quæ portavérunt ætérni Patris Fílium."}],"Postcommunio":[{"k":"text","la":"Hæc nos commúnio, Dómine, purget a crímine: et, intercedénte beáta Vírgine Dei Genetríce María, cœléstis remédii fáciat esse consórtes."},{"k":"macro","name":"Per eundem"}]},"hr":{"f73a189cab197aaa":{"t":"<i>Pomolimo se</i>.\nBože, koji si htio da po anđelovu navještenju tvoja Riječ uzme tijelo u krilu blažene Djevice Marije, daj, smjerno te molimo, da mi koji je priznajemo Bogorodicom, po njezinu zagovoru nađemo pomoć u tebe.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"3aa0de672be3b8a0":{"t":"Tvojim smilovanjem. Gospodine, i zagovorom blažene Marije, vazda Djevice Majke Jedinorođenoga Sina tvoga, koristila nam ova žrtva za vječnu i sadašnju sreću i mir.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"f3420e82111d9894":{"t":"<i>Pomolimo se</i>.\nOva Pričest, Gospodine, neka nas očisti od opačina i zagovorom blažene Djevice Bogorodice Marije neka nas učini dionicima nebeskog lijeka.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"f8a098f3a92b693a":{"t":"Iz 7, 14, Ps 97, 1\n(Iz 7, 14) Evo, Djevica će začeti i roditi Sina i on će se zvati Emanuel. (Ps 97, 1) Pjevajte Gospodinu novu pjesmu, jer učini divna djela.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Iz 7, 14) Evo, Djevica će začeti i roditi Sina i on će se zvati Emanuel."},"2de5fba36a04c0be":{"t":"Sir 24, 23-31\nČitanje knjige Mudrosti. Ja sam kao loza dala ugodan miris, a cvijeće moje rod je slavan i častan. Ja sam majka lijepe ljubavi, straha, znanja i svetoga ufanja. U meni je sva milina življenja i istine, u meni je sva nada života i kreposti. Dođite k meni svi koji me želite i nasitite se plodova mojih. Jer je duh moj slađi od meda i nasljedstvo je moje slađe od medenoga saća. Uspomena je moja trajna kroz naraštaje. Koji mene blaguju još će gladovati i koji mene piju još će žeđati. Tko mene sluša neće se postidjeti, i koji rade po meni neće griješiti. Koji mene slave imat će život vječni."},"67a9368ede89de67":{"t":"Iz 11, 1-2\nIz korjena će Jesejeva izrasti mladica i niknuti cvijet. Na njemu će počivati Duh Gospodnji.\n\nBogorodice Djevo, u tvojem se zatvori krilu postavši čovjek, onaj koga sav svijet ne može obuhvatiti.","v":"∅ → aleluia aleluia; ∅ → aleluia"},"ec6d40b440bbf6c3":{"t":"Lk 2, 43-51\nSlijedi sveto Evanđelje po Luki. U ono vrijeme, kad su se vraćali, dječak Isus ostade u Jeruzalemu, a da njegovi roditelji nisu znali. Misleći da je među suputnicima, išli su dan hoda, a onda ga stanu tražiti među rođacima i znancima. Ali, kako ga ne nađu, vrate se u Jeruzalem da ga traže. Poslije tri dana nađu ga u hramu gdje sjedi među učiteljima, kako ih sluša i postavlja pitanja. Svi koji su ga slušali, divili su se njegovoj mudrosti i odgovorima. Kad ga opaze, vrlo se začude. A majka mu reče: Sine, zašto si nam to učinio? Tvoj otac i ja žalosni smo te tražili. On im odgovori: Zašto ste me tražili? Zar niste znali da ja moram biti u onome što pripada mom Ocu? A oni nisu shvatili njegovih riječi. On tada pođe s njima i dođe u Nazaret i bio im je poslušan."},"28243ab39eeffa19":{"t":"Mt 1, 18\nKad je Marija, Majka njegova, bila zaručena s Josipom, nađe se da je začela po Duhu Svetomu."},"006ab57f0d571d6b":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože: i da te <i>o svetkovini</i> blažene Marije vazda Djevice hvalimo, blagoslivljamo i slavimo. Ona je osjenjena Duhom Svetim začela jedinorođenoga Sina tvoga i sačuvavši slavu djevičanstva prosula svijetom vječno svjetlo Isusa Krista Gospodina našega. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:"},"4cc414b9b992a40d":{"t":"Blaženo tijelo Marije Djevice koje je nosilo Sina vječnoga Oca."}},"variants":{"paschal":{"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Num 17:8"},{"k":"text","la":"Virga Jesse flóruit: Virgo Deum et hóminem génuit: pacem Deus réddidit, in se reconcílians ima summis."},{"k":"ref","la":"Luc 1:28"},{"k":"text","la":"Ave, María, grátia plena; Dóminus tecum: benedícta tu in muliéribus. Allelúja."}],"Tractus":[{"k":"text","la":"Gaude, María Virgo, cunctas hǽreses sola interemísti."},{"k":"text","la":"Quæ Gabriélis Archángeli dictis credidísti.","mark":"V"},{"k":"text","la":"Dum Virgo Deum et hóminem genuísti: et post partum, Virgo, invioláta permansísti.","mark":"V"},{"k":"text","la":"Dei Génetrix, intercéde pro nobis.","mark":"V"}]}}});
